function compareJson(input) {
  requireObject(input);
  if (!Object.hasOwn(input, 'before') || !Object.hasOwn(input, 'after')) {
    throw new Error('Provide before and after');
  }
  const { ignorePaths = [] } = input;
  if (!Array.isArray(ignorePaths) || ignorePaths.length > 100 ||
      ignorePaths.some(path => typeof path !== 'string' || !/^\/(?:[^~]|~[01])*$/u.test(path))) {
    throw new Error('Provide up to 100 non-root JSON Pointers in ignorePaths');
  }
  const ignored = new Set(ignorePaths);
  const changes = [];
  function walk(before, after, path, depth) {
    if (depth > 50) throw new Error('Maximum nesting depth is 50');
    if (Object.is(before, after)) return;
    const beforeObject = before !== null && typeof before === 'object';
    const afterObject = after !== null && typeof after === 'object';
    if (!beforeObject || !afterObject || Array.isArray(before) !== Array.isArray(after)) {
      changes.push({ path, type: 'changed', before, after });
      return;
    }
    const keys = new Set([...Object.keys(before), ...Object.keys(after)]);
    for (const key of keys) {
      const pointer = path + '/' + key.replaceAll('~', '~0').replaceAll('/', '~1');
      if (ignored.has(pointer)) continue;
      if (!Object.hasOwn(before, key)) changes.push({ path: pointer, type: 'added', after: after[key] });
      else if (!Object.hasOwn(after, key)) changes.push({ path: pointer, type: 'removed', before: before[key] });
      else walk(before[key], after[key], pointer, depth + 1);
    }
  }
  walk(input.before, input.after, '', 0);
  return { equal: changes.length === 0, changes };
}


