function maskText(input) {
  if (!input || typeof input.text !== 'string' || input.text.length > 20000) {
    throw new Error('Provide text up to 20000 UTF-16 code units');
  }
  const allowed = ['email', 'phone', 'ipv4'];
  const types = input.types ?? allowed;
  if (!Array.isArray(types) || types.some(t => !allowed.includes(t))) throw new Error('types must contain email, phone or ipv4');
  const candidates = [];
  const patterns = {
    email: /(?<![A-Za-z0-9.!#$%&'*+/=?^_`{|}~-])[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)+/g,
    phone: /(?<![\d+])(?:\+82[ -]?10[ -]?\d{4}[ -]?\d{4}|010[ -]?\d{4}[ -]?\d{4}|\+1[ -]?(?:\(\d{3}\)|\d{3})[ -]?\d{3}[ -]?\d{4})(?!\d)/g,
    ipv4: /(?<![\d.])(?:\d{1,3}\.){3}\d{1,3}(?![\d.])/g,
  };
  for (const type of new Set(types)) {
    for (const match of input.text.matchAll(patterns[type])) {
      if (type === 'ipv4' && match[0].split('.').some(part => Number(part) > 255)) continue;
      candidates.push({type, start:match.index, end:match.index + match[0].length});
    }
  }
  candidates.sort((a,b) => a.start - b.start || b.end - a.end);
  const matches = [];
  for (const item of candidates) if (!matches.length || item.start >= matches.at(-1).end) matches.push(item);
  let text = '', cursor = 0;
  const counts = {email:0, phone:0, ipv4:0};
  for (const item of matches) {
    text += input.text.slice(cursor,item.start) + '[' + item.type.toUpperCase() + ']';
    cursor = item.end;
    counts[item.type]++;
  }
  text += input.text.slice(cursor);
  return {text, counts, total:matches.length, scope:'Pattern-based: email, Korean mobile 010/+82 10, US/Canada +1, IPv4. May miss personal data; review output.'};
}

const MAX_ROWS = 5000, MAX_COLUMNS = 250;
function parseCsv(csv) {
  const source = csv.replace(/^\uFEFF/, '').replace(/\r\n?/g, '\n');
  const records = [];
  let fields = [], field = '', state = 'start', line = 1, rowLine = 1;
  function addField() {
    fields.push(field);
    if (fields.length > MAX_COLUMNS) throw Error('Maximum 250 columns');
    field = '';
    state = 'start';
  }
  function addRecord() {
    addField();
    if (fields.some(value => value.trim())) records.push({ line: rowLine, fields });
    if (records.length > MAX_ROWS + 1) throw Error('Maximum 5000 data rows');
    fields = [];
  }
  for (let i = 0; i < source.length; i++) {
    const char = source[i];
    if (state === 'quoted') {
      if (char === '"' && source[i + 1] === '"') {
        field += '"';
        i++;
      } else if (char === '"') state = 'closed';
      else {
        field += char;
        if (char === '\n') line++;
      }
      continue;
    }
    if (char === ',') addField();
    else if (char === '\n') {
      addRecord();
      rowLine = ++line;
    } else if (char === '"' && state === 'start') state = 'quoted';
    else {
      if (char === '"' || state === 'closed') throw Error('Unexpected quote or trailing text on line ' + line);
      field += char;
      state = 'unquoted';
    }
  }
  if (state === 'quoted') throw Error('Unclosed quoted field starting on row ' + rowLine);
  if (fields.length || field || state === 'closed') addRecord();
  return records;
}

function aggregate(csv, mapping, carryOrder) {
  if (typeof csv !== 'string' || new TextEncoder().encode(csv).length > 262144) {
    throw Error('Provide UTF-8 CSV text up to 256 KiB');
  }
  const [header, ...rows] = parseCsv(csv);
  const names = header?.fields;
  if (!names || new Set(names).size !== names.length) throw Error('Provide unique CSV headers');
  const indexes = ['order','sku','quantity'].map(key => names.indexOf(mapping[key]));
  if (indexes.some(index => index < 0)) throw Error('Missing mapped CSV column');
  if (!rows.length) throw Error('Provide at least one data row in each CSV');
  const items = new Map();
  let previousOrder = '';
  for (const {line, fields} of rows) {
    if (fields.length !== names.length) throw Error('Incorrect column count on line ' + line);
    const [orderIndex, skuIndex, quantityIndex] = indexes;
    const order = fields[orderIndex].trim() || (carryOrder ? previousOrder : '');
    const sku = fields[skuIndex].trim();
    const quantityText = fields[quantityIndex].trim();
    const quantity = Number(quantityText);
    if (!order || !sku || !/^\d+$/.test(quantityText) || !Number.isSafeInteger(quantity)) {
      throw Error('Provide order ID, SKU and nonnegative integer quantity on line ' + line);
    }
    previousOrder = order;
    const key = JSON.stringify([order,sku]);
    const item = items.get(key) ?? {order,sku,quantity:0};
    if (!Number.isSafeInteger(item.quantity + quantity)) throw Error('Quantity total too large');
    item.quantity += quantity;
    items.set(key,item);
  }
  return items;
}

function compareOrderQuantities(input) {
  if (input.scopeConfirmed !== true) throw Error('Set scopeConfirmed=true only after filtering both files to the same orders and period, excluding cancellations, refunds and unshipped records.');

  const expected = aggregate(input.ordersCsv,
    {order:'Name',sku:'Lineitem SKU',quantity:'Lineitem quantity'}, true);
  const actual = aggregate(input.shipmentsCsv,
    input.shipmentColumns ?? {order:'Order Number',sku:'SKU',quantity:'Quantity'}, false);
  const differences = [];
  for (const [key, item] of expected) {
    const shipped = actual.get(key)?.quantity ?? 0;
    if (shipped !== item.quantity) differences.push({...item,shipped,delta:shipped-item.quantity});
  }
  for (const [key,item] of actual) {
    if (!expected.has(key)) differences.push({order:item.order,sku:item.sku,quantity:0,shipped:item.quantity,delta:item.quantity});
  }
  const cell = value => {
    let text = String(value);
    if (typeof value === 'string' && /^[=+@\t\r-]/.test(text)) text = "'" + text;
    return '"' + text.replaceAll('"', '""') + '"';
  };
  const reportCsv=['order,sku,expected,actual,delta',...differences.map(i=>[i.order,i.sku,i.quantity,i.shipped,i.delta].map(cell).join(','))].join('\n');
  return {matched: differences.length === 0, comparedPairs:expected.size, differenceCount:differences.length, differences,reportCsv,scope:'Quantity comparison only; supplied files must already exclude cancellations, refunds and unshipped records. Not payment reconciliation or proof of delivery.'};
}


const operations = new Set(['get','put','post','delete','options','head','patch','trace']);
const isObject = value => value !== null && typeof value === 'object' && !Array.isArray(value);

function redirectPath(value) {
  if (typeof value !== 'string' || !/^\/(?!\/)[^\\?#\s]*$/.test(value) || value.length > 500) {
    throw Error('Use a site-relative path without query or fragment');
  }
  const normalized = new URL(value, 'https://example.invalid').pathname;
  if (normalized.startsWith('//') || /%(?:2f|5c|00)/i.test(normalized) || /[\x00-\x1f\x7f]/.test(value)) {
    throw Error('Use an unambiguous same-site redirect path');
  }
  return normalized;
}

function readRedirectCsv(csv) {
  if (typeof csv !== 'string') throw Error('Provide Shopify redirect CSV text');
  const [header, ...rows] = parseCsv(csv);
  const fields = header?.fields.map(field => field.trim().toLowerCase());
  if (fields?.length !== 2 || !fields.includes('redirect from') || !fields.includes('redirect to')) {
    throw Error('Use the Shopify CSV columns Redirect from and Redirect to');
  }
  return rows.map(({ line, fields: cells }) => {
    if (cells.length !== 2) throw Error('Expected two columns on CSV line ' + line);
    return {
      from: cells[fields.indexOf('redirect from')].trim(),
      to: cells[fields.indexOf('redirect to')].trim(),
    };
  });
}

function shopifyReserved(path) {
  const clean = path.toLowerCase().replace(/\/+$/, '');
  return /^\/(apps|application|cart|carts|orders|services|shop|a|community|tools)(?:\/|$)/.test(clean) ||
    /^\/(products|collections(?:\/(all|vendors|types))?)$/.test(clean) ||
    /^\/collections\/[^/]+\/[^/]+$/.test(clean);
}

function auditRedirects({ redirects, csv, output = 'report' } = {}) {
  if (!['report', 'shopify-csv'].includes(output)) throw Error('Use output report or shopify-csv');
  if (csv !== undefined) {
    if (redirects !== undefined) throw Error('Provide either redirects or csv');
    redirects = readRedirectCsv(csv);
  }
  if (!Array.isArray(redirects) || redirects.length < 1 || redirects.length > 1000) throw Error('Provide 1–1000 redirects');
  const edges = new Map(), conflicts = new Set();
  for (const { from, to } of redirects) {
    const start = redirectPath(from), end = redirectPath(to);
    if (edges.has(start) && edges.get(start) !== end) conflicts.add(start);
    else edges.set(start, end);
  }
  const findings = [], resolved = new Map(), flattened = [];
  let blocked = false;
  for (const start of edges.keys()) {
    const chain = [], seen = new Set();
    let current = start;
    while (edges.has(current) && !seen.has(current) && !conflicts.has(current) && !resolved.has(current)) {
      chain.push(current);
      seen.add(current);
      current = edges.get(current);
    }
    let result = resolved.get(current);
    if (!result) {
      if (conflicts.has(current)) result = { issue: 'ambiguous_destination', at: current };
      else if (seen.has(current)) result = { issue: 'loop', at: current };
      else result = { hops: 0, destination: current };
    }
    for (const path of chain.reverse()) {
      if (!result.issue) result = { hops: result.hops + 1, destination: result.destination };
      resolved.set(path, result);
    }
    if (result.issue) {
      findings.push({ start, ...result });
      blocked = true;
    } else {
      if (result.hops > 1) findings.push({ start, issue: 'chain', ...result });
      if (output === 'shopify-csv') {
        if (shopifyReserved(start) || start.toLowerCase() === result.destination.toLowerCase() + '.html') {
          findings.push({ start, issue: 'shopify_unsupported_source' });
          blocked = true;
        }
        flattened.push([start, result.destination]);
      }
    }
  }
  const report = { passed: findings.length === 0, redirects: edges.size, findings };
  if (output === 'shopify-csv') {
    const quote = value => '"' + value.replaceAll('"', '""') + '"';
    report.shopifyCsv = blocked ? null : 'Redirect from,Redirect to\n' +
      flattened.map(row => row.map(quote).join(',')).join('\n') + '\n';
    report.exportBlocked = blocked;
  }
  return report;
}

function checkContract({ before, after } = {}) {
  if (![before,after].every(doc=>isObject(doc?.paths) && /^3\.[01]\./.test(doc.openapi ?? ''))) {
    throw Error('Provide before and after OpenAPI 3.0 or 3.1 JSON documents');
  }
  const findings = [];
  for (const [path, item] of Object.entries(before.paths)) {
    if (!isObject(item)) continue;
    for (const [method, op] of Object.entries(item)) {
      if (!operations.has(method) || !isObject(op)) continue;
      const next = after.paths[path]?.[method];
      if (!isObject(next)) {
        findings.push({ path, method, issue: 'operation_removed' });
        continue;
      }
      const parameters = (pathItem, operation) => {
        const params = new Map();
        for (const source of [pathItem?.parameters, operation.parameters]) {
          if (!Array.isArray(source)) continue;
          for (const param of source) if (typeof param?.name === 'string' && typeof param.in === 'string') {
            params.set(param.in + ':' + param.name, param.required === true);
          }
        }
        return params;
      };
      const previous = parameters(item, op);
      for (const [parameter, required] of parameters(after.paths[path], next)) {
        if (required && !previous.get(parameter)) findings.push({ path, method, parameter, issue: 'parameter_now_required' });
      }
      if (next.requestBody?.required === true && op.requestBody?.required !== true) {
        findings.push({ path, method, issue: 'request_body_now_required' });
      }
    }
  }
  return { passed: findings.length === 0, findings, scope: 'Inline operations, required parameters and request bodies' };
}

function auditDeliveries({ deliveries } = {}) {
  if (!Array.isArray(deliveries) || deliveries.length < 1 || deliveries.length > 1000) throw Error('Provide 1–1000 deliveries');
  const events = new Map();
  for (const [index, delivery] of deliveries.entries()) {
    const { eventId, status } = delivery ?? {};
    if (typeof eventId !== 'string' || !eventId.trim() || eventId.length > 160 || !Number.isInteger(status) || status < 100 || status > 599) {
      throw Error('Invalid eventId or HTTP status at index ' + index);
    }
    const group = events.get(eventId) ?? { eventId, attempts: 0, successes: 0, lastStatus: status };
    group.attempts++;
    if (status >= 200 && status < 300) group.successes++;
    group.lastStatus = status;
    events.set(eventId, group);
  }
  const duplicateSuccesses = [], unresolved = [];
  for (const group of events.values()) {
    if (group.successes > 1) duplicateSuccesses.push(group);
    if (!group.successes) unresolved.push(group);
  }
  return { events: events.size, duplicateSuccesses, unresolved };
}

function reconcile(input = {}) {
  if ('ordersCsv' in input || 'shipmentsCsv' in input) return compareOrderQuantities(input);
  const {expected, received}=input;
  function index(rows) {
    if (!Array.isArray(rows) || rows.length > 1000) throw Error('Provide arrays of up to 1000 entries');
    const out = new Map();
    for (const row of rows) {
      const { id, amountMinor, currency } = row ?? {};
      if (typeof id !== 'string' || !id.trim() || id.length > 160 || out.has(id) ||
          !Number.isSafeInteger(amountMinor) || typeof currency !== 'string' || !/^[A-Z]{3}$/.test(currency)) {
        throw Error('Require unique IDs, integer minor units and three-letter currency codes');
      }
      out.set(id, { id, amountMinor, currency });
    }
    return out;
  }
  const a = index(expected), b = index(received);
  const missing = [], unexpected = [], mismatched = [];
  for (const [id, row] of a) {
    const actual = b.get(id);
    if (!actual) missing.push(row);
    else if (actual.currency !== row.currency || actual.amountMinor !== row.amountMinor) mismatched.push({ id, expected: row, received: actual });
  }
  for (const [id, row] of b) if (!a.has(id)) unexpected.push(row);
  return { matched: a.size - missing.length - mismatched.length, missing, unexpected, mismatched };
}

